function crop(p){const index=products.indexOf(p);if(p.frame){const [w,y,h]=p.frame;return `<div class="original-frame" style="aspect-ratio:${w}/${h}"><img src="assets/${p.image}" alt="${p.kind} ${p.name}" style="top:-${y/h*100}%" loading="lazy"></div>`}return `<img class="catalog-photo" src="assets/${p.image||'producto-'+index+'.png'}" alt="${p.kind||'Colchón'} ${p.name} de Manufacturas Bell" decoding="async">`}
let filter='Todos';const search=document.querySelector('#search');
function render(){const query=search.value.toLocaleLowerCase('es').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const visible=products.slice(0,6).filter(p=>(filter==='Todos'||p.sizes.includes(filter))&&p.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query));document.querySelector('#products').innerHTML=visible.map(p=>`<article class="product"><div class="product-picture"><span class="tag">MANUFACTURAS BELL</span>${crop(p)}</div><div class="product-title"><h3>${p.name}</h3><button class="more" data-product="${products.indexOf(p)}" aria-label="Ver detalles de ${p.name}">↗</button></div><p>${p.desc}</p><div class="sizes">${p.sizes.join(' · ')}</div><label class="size-label">Medida<select data-size="${products.indexOf(p)}">${p.sizes.map(size=>`<option value="${size}">${size}</option>`).join('')}</select></label><button class="add-cart" data-add="${products.indexOf(p)}">Agregar +</button></article>`).join('');document.querySelector('#empty').hidden=visible.length!==0;document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(Number(b.dataset.product)));}
