function readCart(){try{const stored=JSON.parse(localStorage.getItem('bell-cart')||'[]');return Array.isArray(stored)?stored.filter(x=>Number.isInteger(x.id)&&products[x.id]&&products[x.id].sizes.includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99).slice(0,100):[]}catch(e){return []}}
let cart=readCart();
const cartDialog=document.querySelector('#cart-dialog'),advisorDialog=document.querySelector('#advisor-dialog');
function saveCart(){try{localStorage.setItem('bell-cart',JSON.stringify(cart))}catch(e){}updateCartBadge()}
function updateCartBadge(){document.querySelector('#cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0);document.querySelector('#cart-open').setAttribute('aria-label','Abrir carrito: '+cart.reduce((n,x)=>n+x.qty,0)+' productos')}
let toastTimer;function notifyCart(text){const toast=document.querySelector('#cart-toast');toast.textContent=text;toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,2600)}
document.querySelector('main').addEventListener('click',e=>{const button=e.target.closest('[data-add]');if(!button)return;const id=Number(button.dataset.add),size=button.parentElement.querySelector(`[data-size="${id}"]`).value;const existing=cart.find(x=>x.id===id&&x.size===size);if(existing){if(existing.qty>=99){notifyCart('Máximo 99 unidades por selección');return}existing.qty++}else cart.push({id,size,qty:1});saveCart();notifyCart(products[id].name+' agregado al carrito')});
function renderCart(){document.querySelector('#cart-items').innerHTML=cart.length?cart.map((x,i)=>`<div class="cart-row"><div class="cart-thumb">${crop(products[x.id])}</div><div><strong>${products[x.id].name}</strong><small>${x.size}</small><div class="quantity"><button data-change="${i}" data-delta="-1" aria-label="Reducir cantidad de ${products[x.id].name}">−</button><span>${x.qty}</span><button data-change="${i}" data-delta="1" aria-label="Aumentar cantidad de ${products[x.id].name}">+</button><button data-remove="${i}" class="remove">Quitar</button></div></div></div>`).join(''):'<p class="empty-cart">Tu carrito está vacío. Explora los colchones y agrega tus favoritos.</p>';document.querySelector('#cart-confirm').disabled=!cart.length;updateCartBadge()}
document.querySelector('#cart-open').onclick=()=>{renderCart();cartDialog.showModal()};
document.querySelector('#cart-items').onclick=e=>{const remove=e.target.closest('[data-remove]'),change=e.target.closest('[data-change]');if(remove)cart.splice(Number(remove.dataset.remove),1);if(change){const i=Number(change.dataset.change);cart[i].qty=Math.min(99,cart[i].qty+Number(change.dataset.delta));if(cart[i].qty<=0)cart.splice(i,1)}saveCart();renderCart()};
