let mapAnimation;const mapSvg=document.querySelector('.state-map');
function mapView(target){document.querySelectorAll('.state-pin').forEach(p=>p.setAttribute('r',Math.max(1.8,target[2]/120)));document.querySelectorAll('.state-label').forEach(p=>p.style.fontSize=(target[2]/43)+'px');cancelAnimationFrame(mapAnimation);const from=mapSvg.getAttribute('viewBox').split(' ').map(Number),start=performance.now();if(matchMedia('(prefers-reduced-motion: reduce)').matches){mapSvg.setAttribute('viewBox',target.join(' '));return}function step(now){const t=Math.min(1,(now-start)/650),ease=1-Math.pow(1-t,3);mapSvg.setAttribute('viewBox',from.map((v,i)=>v+(target[i]-v)*ease).join(' '));if(t<1)mapAnimation=requestAnimationFrame(step)}mapAnimation=requestAnimationFrame(step)}
