// URLs estables por categoría y modelo; compatibles con alojamiento estático.
function productSlug(p){return ((p.kind||'colchon')+'-'+p.name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/-$/,'')}
function productURL(i){const u=new URL('index.html',location.href);u.searchParams.set('producto',productSlug(products[i]));return u.href}
function productLink(p){const i=products.indexOf(p);return `<a class="related-card" href="${productURL(i)}"><div>${crop(p)}</div><h3>${p.kind||'Colchón'} ${p.name}</h3><span>Ver producto ↗</span></a>`}
function linkCatalog(){document.querySelectorAll('.product').forEach(card=>{const button=card.querySelector('[data-product]');if(!button)return;const i=Number(button.dataset.product);for(const el of [card.querySelector('.product-picture'),card.querySelector('h3')]){if(!el||el.closest('a'))continue;const a=document.createElement('a');a.href=productURL(i);a.className='product-link';a.setAttribute('aria-label','Ver '+products[i].name);el.replaceWith(a);a.append(el)}})}
linkCatalog();const catalogObserver=new MutationObserver(linkCatalog);catalogObserver.observe(document.querySelector('#products'),{childList:true});
if(new URLSearchParams(location.search).has('producto')){
 document.body.classList.add('product-page');
 document.querySelectorAll('header a,footer a').forEach(a=>{if(a.getAttribute('href')?.startsWith('#'))a.href='index.html'+a.getAttribute('href')});
 const slug=new URLSearchParams(location.search).get('producto');const i=products.findIndex(p=>productSlug(p)===slug);const page=document.createElement('section');page.id='product-page';document.querySelector('main').append(page);
 if(i<0){page.innerHTML='<h1>Producto no encontrado</h1><p>Explora nuestros modelos para encontrar tu próximo descanso.</p><a class="button" href="index.html#coleccion">Ver catálogo</a>'}
 else{const p=products[i],kind=p.kind||'Colchón',photos=p.photos||[p.image||'producto-'+i+'.png'];document.title=kind+' '+p.name+' | Manufacturas Bell';document.querySelector('meta[name="description"]').content=p.desc;
 page.innerHTML=`<a class="back-catalog" href="index.html#${p.kind==='Cama'?'camas':p.kind==='Combo'?'combos':'coleccion'}">← Volver al catálogo</a><div class="product-layout"><div class="product-gallery"><div class="gallery-stage"><img id="gallery-main" src="assets/${photos[0]}" alt="${kind} ${p.name}" fetchpriority="high"></div><div class="gallery-thumbnails" aria-label="Fotografías del producto">${photos.map((photo,n)=>`<button data-photo="${n}" aria-label="Ver fotografía ${n+1}" aria-pressed="${n===0}"><img src="assets/${photo}" alt="Vista ${n+1} de ${p.name}"></button>`).join('')}</div><p class="photo-caption">${photos.length===1?'Fotografía del producto':'Selecciona una fotografía para ampliarla'}</p></div><div class="product-info"><div class="eyebrow">MANUFACTURAS BELL · ${kind.toUpperCase()}</div><h1>${kind} ${p.name}</h1><p class="product-description">${p.desc}</p><p>Fabricantes con 19 años de trayectoria ofreciéndote un buen descanso.</p><label class="size-label">Elige la medida<select data-size="${i}">${p.sizes.map(size=>`<option>${size}</option>`).join('')}</select></label><button class="add-cart" data-add="${i}">Agregar al carrito +</button><div class="product-share"><button id="share-product" class="button">Compartir</button></div><input id="product-url" aria-label="Enlace del producto" readonly value="${productURL(i)}"><p id="share-status" role="status"></p><div class="product-note"><strong>Tenemos servicio de apartado</strong><p>Consulta disponibilidad, dimensiones, accesorios incluidos y condiciones con un asesor al finalizar tu selección.</p></div></div></div><section class="related-section"><div class="eyebrow">MÁS OPCIONES PARA TU DESCANSO</div><h2>${kind==='Colchón'?'Otros colchones':kind==='Cama'?'Otras camas':'Otros combos'}</h2><div class="related-grid">${products.filter(x=>x!==p&&(x.kind||'Colchón')===kind).map(productLink).join('')}</div></section>`;
 page.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{page.querySelector('#gallery-main').src='assets/'+photos[Number(b.dataset.photo)];page.querySelectorAll('[data-photo]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});
 const copy=async()=>{const field=page.querySelector('#product-url'),status=page.querySelector('#share-status');try{await navigator.clipboard.writeText(field.value);status.textContent='Enlace copiado.'}catch(e){field.focus();field.select();let copied=false;try{copied=document.execCommand('copy')}catch(e){}status.textContent=copied?'Enlace copiado.':'Selecciona y copia el enlace que aparece arriba.'}};
 page.querySelector('#share-product').onclick=copy;
 }
}

// Restaurar el estado también cuando el navegador recupera una página con Atrás.
function restoreBellState(){
 let theme;try{theme=localStorage.getItem('bell-theme')}catch(e){}
 if(theme==='light'||theme==='dark')setTheme(theme);
 cart=readCart();renderCart();
}
window.addEventListener('pageshow',restoreBellState);
window.addEventListener('storage',event=>{if(event.key==='bell-cart'||event.key==='bell-theme'||event.key===null)restoreBellState()});
